begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_schema('bunly_analysis_private', 'analysis private schema exists');
select is((select count(*)::int from pg_class c join pg_namespace n on n.oid=c.relnamespace
  where n.nspname='bunly_analysis_private' and c.relkind='r' and c.relrowsecurity), 3, 'all analysis tables have RLS');
select ok(not has_schema_privilege('authenticated', 'bunly_analysis_private', 'USAGE'), 'client cannot access private schema');
select ok(not has_function_privilege('anon', 'public.bunly_analysis_begin(uuid,uuid,text)', 'EXECUTE'), 'anon cannot reserve quota');
select ok(not has_function_privilege('authenticated', 'public.bunly_analysis_begin(uuid,uuid,text)', 'EXECUTE'), 'authenticated cannot choose RPC owner');
select ok(not has_function_privilege('authenticated', 'public.bunly_analysis_finish(uuid,uuid,bigint,jsonb,text)', 'EXECUTE'), 'client cannot finalize quota');
select ok((select bool_and(not prosecdef) from pg_proc where proname in ('bunly_analysis_begin','bunly_analysis_finish')), 'analysis RPCs are invoker functions');
insert into auth.users(id,email) values ('21000000-0000-0000-0000-000000000001','a05-rls@example.test');
insert into bunly_analysis_private.entitlements(user_id,daily_limit) values ('21000000-0000-0000-0000-000000000001',1);
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"21000000-0000-0000-0000-000000000001","role":"authenticated"}', true);
select throws_ok($$select * from bunly_analysis_private.requests$$, '42501', null, 'client cannot read private request ledger');
select throws_ok($$update bunly_analysis_private.entitlements set daily_limit=10000$$, '42501', null, 'client cannot upgrade own limit');
select throws_ok($$select public.bunly_analysis_begin('21000000-0000-0000-0000-000000000001','31000000-0000-0000-0000-000000000001',repeat('a',64))$$, '42501', null, 'client cannot invoke server-only reserve');
set local role service_role;
select is(public.bunly_analysis_begin('21000000-0000-0000-0000-000000000001','31000000-0000-0000-0000-000000000001',repeat('a',64))->>'status', 'claimed', 'server reserves once');
select is(public.bunly_analysis_begin('21000000-0000-0000-0000-000000000001','31000000-0000-0000-0000-000000000001',repeat('a',64))->>'status', 'processing', 'duplicate processing does not reserve twice');
select is(public.bunly_analysis_begin('21000000-0000-0000-0000-000000000001','31000000-0000-0000-0000-000000000002',repeat('a',64))->>'status', 'quota_exceeded', 'last reservation blocks another request');
select is(public.bunly_analysis_finish('21000000-0000-0000-0000-000000000001','31000000-0000-0000-0000-000000000001',1,'{"matches":[]}',null)->>'status', 'succeeded', 'valid no-match commits');
select is(public.bunly_analysis_finish('21000000-0000-0000-0000-000000000001','31000000-0000-0000-0000-000000000001',1,null,'timeout')->>'status', 'succeeded', 'late error cannot refund committed success');
select is((select successes from bunly_analysis_private.usage where user_id='21000000-0000-0000-0000-000000000001'),1,'success counted exactly once');
select is((select reserved from bunly_analysis_private.usage where user_id='21000000-0000-0000-0000-000000000001'),0,'reservation closed');
reset role;
select * from finish();
rollback;
